Path('qa/m6-runtime-state-smoke.mjs').write_text('''import assert from "node:assert/strict";\nimport { adaptLegacyConflictState, projectM6ConflictState, m6ApplyPostResolutionState, m6AdvanceAfterActionState, m6ApplyManeuverState, m6FinishConflictState, m6CompromiseGrade } from "../module/core/m6-conflict-runtime.mjs";\nconst base={id:"c1",active:true,name:"Fight",type:"fight",stage:"action",exchange:1,currentIndex:0,ranger:{participantIds:["r1","r2"],captainId:"r1",goal:"Win",disposition:{start:8,current:8}},gm:{actorId:"g1",goal:"Stop",disposition:{start:7,current:7}},locks:{gm:true,ranger:true},revealed:[{index:0,gmAction:"attack",rangerAction:"defend",rangerActorId:"r1"}],rolls:{gm:{},ranger:{}},effects:{gm:{nextDice:0,disabledGearIds:[]},ranger:{nextDice:0,disabledGearIds:[]}},actionCounts:{r1:0,r2:0},pendingActionCounts:{r1:1,r2:0},lastRangerActorId:null,pendingLastRangerActorId:"r1",weaponIds:{r1:"gear:x"},outcome:null,compromise:null,log:[]};\nconst runtime=adaptLegacyConflictState(base); assert.equal(runtime.schema,"M6_CONFLICT_RUNTIME_V1"); assert.equal(runtime.participants.length,3);\nconst resolved=m6ApplyPostResolutionState(base,{pair:{gmAction:"attack",rangerAction:"defend",gmMode:"versus",rangerMode:"versus"},result:{gmPassed:true,rangerPassed:false,gmMargin:2,rangerMargin:0,gmEffectiveSuccesses:4,rangerEffectiveSuccesses:2}});\nassert.equal(resolved.ranger.disposition.current,6); assert.equal(resolved.stage,"action");\nconst advanced=m6AdvanceAfterActionState(resolved); assert.equal(advanced.currentIndex,1); assert.equal(advanced.stage,"ready");\nconst manBase={...base,stage:"maneuver",pendingManeuver:{side:"ranger",margin:3},pendingManeuverQueue:[{side:"ranger",margin:3}],effects:{gm:{nextDice:0,disabledGearIds:[]},ranger:{nextDice:0,disabledGearIds:[]}}};\nconst man=m6ApplyManeuverState(manBase,{choice:"combo"}); assert.equal(man.effects.gm.nextDice,-1); assert.equal(man.effects.ranger.nextDice,2); assert.equal(man.pendingManeuver,null);\nconst dis=m6ApplyManeuverState(manBase,{choice:"disarm",disarmedGearId:"sword"}); assert.deepEqual(dis.effects.gm.disabledGearIds,["sword"]);\nconst ended={...base,outcome:{winner:"ranger"},ranger:{...base.ranger,disposition:{start:8,current:4}},stage:"compromise"}; const fin=m6FinishConflictState(ended,{text:"Deal"}); assert.equal(fin.compromise.grade,"compromise"); assert.equal(fin.active,false); assert.equal(m6CompromiseGrade(8,5),"minor");\nassert.equal(projectM6ConflictState(advanced).currentIndex,1); console.log("PASS m6-runtime-state-smoke");\n''')

Path('TEST_PROTOCOL_v1.8.0-qa.6.md').write_text('''# Realm Guard / Torchbearer v1.8.0-qa.6 QA — M6 Runtime & State Authority\n\n## Scope\nOne consolidated M6 patch: CORE runtime model + state-transition authority for disposition, Maneuver state/effects, action/exchange advancement, outcome and compromise state. Resolution-result authority remains independently protected. Legacy remains writer for Learning, Nature tax, interactive tie transaction and private hidden-plan repository.\n\n## 0. Initial status\n```js\ngame.system.version\ngame.realmGuard.core.m6.getStatus()\ngame.realmGuard.core.m6.handoffStatus()\ngame.realmGuard.core.m6.stateHandoffStatus()\ngame.realmGuard.core.m6.runtimeSnapshot()\n```\nExpected version 1.8.0-qa.6; resolution and state handoffs enabled; no rollback reasons. Runtime snapshot uses `M6_CONFLICT_RUNTIME_V1`.\n\n## 1. Normal Versus + disposition + advancement\nRun Attack vs Defend with a non-tie result. Verify correct pass/fail, disposition change, chat result and automatic movement to the next Action.\nExpected state telemetry: matches increase, mismatches 0, errorFallbacks 0.\n\n## 2. Independent + Trumped\nResolve Attack vs Attack (non-missile) and Attack vs Feint. Verify independent damage/trumped behavior remains unchanged and state progresses correctly.\n\n## 3. Automatic Versus tie\nCreate a supported automatic tie resolution. Verify winner/margin and disposition remain correct. An unresolved interactive tie must stay pending with no state write; that transaction remains deferred.\n\n## 4. Defend recovery\nDamage one side, then resolve a successful Defend. Verify recovery is capped at starting Disposition.\n\n## 5. Maneuver effects\nExercise: Impede (-1D next test), Gain Position (+2D next test), Combo (-1D/+2D), Disarm (selected equipped Gear disabled). Verify pending queue, sequential dual Maneuver handling, effect consumption and later action advancement.\n\n## 6. Three Actions -> next Exchange\nComplete all three Action pairs. Verify Exchange increments, current Action resets to 1, locks reset, planning returns to GM Planning, hidden plans clear, and a new Exchange Weapon / Tool may be declared.\n\n## 7. Outcome + compromise\nReduce one side to 0. Verify winner/tie, ended Exchange/Action and Compromise stage. Finish with compromise text; verify grade (none/minor/compromise/major or tie), Conflict becomes inactive and completion chat is correct.\n\n## 8. Multi-Ranger + Exchange Tool scope\nUse 2+ Rangers. Verify action assignment fairness/no consecutive Ranger rule, independent Actor-scoped Exchange Weapon / Tool declarations, and correct participant in each revealed Action.\n\n## 9. Reload/recovery\nAt minimum reload in: planning, mid-Action after one side has rolled, Maneuver stage, and new Exchange planning. Verify the active Conflict reopens with the same public runtime state and can continue.\n\n## 10. Token Actor regression\nUse an unlinked Token Actor with token-specific equipment. Verify Conflict still resolves equipment/tool source from the token Actor.\n\n## 11. qa.5 stacking regression\nOpen several roll/transient dialogs from Conflict. They must remain above Conflict every time.\n\n## 12. Final telemetry\n```js\ngame.realmGuard.core.m6.handoffStatus()\ngame.realmGuard.core.m6.stateHandoffStatus()\ngame.realmGuard.core.m6.getStatus()\n```\nPASS requires resolution mismatches 0/errorFallbacks 0; state mismatches 0/errorFallbacks 0; both enabled; shadow mismatches 0.\n\n## Rollback isolation test (optional but recommended)\n```js\ngame.realmGuard.core.m6.rollbackCoreState("QA_ISOLATION_TEST")\ngame.realmGuard.core.m6.stateHandoffStatus()\ngame.realmGuard.core.m6.handoffStatus()\n```\nExpected only state authority becomes Legacy; resolution remains CORE_M6. Then restore:\n```js\ngame.realmGuard.core.m6.enableCoreState()\n```\n''')

Path('release/NOTES.md').write_text('''Realm Guard / Torchbearer v1.8.0-qa.6 — M6 Runtime & State Authority.\n\nThis is a consolidated M6 patch, not a micro-patch. It adds the CORE Conflict runtime model (ConflictState/Sides/Teams/Participants/ActionSet projection), pure CORE state services for disposition, Maneuver state/effects, action/exchange advancement, outcome and compromise, plus a separately protected live state-transition handoff.\n\nResolution-result authority from qa.3 remains independently protected. A state mismatch rolls back only CORE state authority; it does not disable the already verified resolution authority. Legacy remains authoritative for Learning writes, Nature tax, the interactive unresolved-tie transaction, and private hidden-plan persistence.\n\nIncludes the previously verified qa.4 Exchange Weapon/Tool scope and qa.5 window stacking behavior unchanged.\n\nQA protocol: TEST_PROTOCOL_v1.8.0-qa.6.md\n''')
